const attr = (go, extra='') => `data-go="${go}" ${extra}`;
const action = (name, extra='') => `data-action="${name}" ${extra}`;
const ib=(name,label,attrs='',cls='')=>`<button class="icon-button ${cls}" aria-label="${esc(label)}" ${attrs}>${icon(name)}</button>`;
const primary=(label,attrs='',cls='')=>`<button class="primary ${cls}" ${attrs}>${label}</button>`;
const tertiary=(label,attrs='',sym='arrow-up-right')=>`<button class="tertiary" ${attrs}>${esc(label)}${sym?icon(sym):''}</button>`;
const heading=(title,link='',go='')=>`<div class="section-heading"><h2>${title}</h2>${link?tertiary(link,attr(go),'chevron-right'):''}</div>`;
const chip=(label,selected=false,attrs='')=>`<button class="chip ${selected?'selected':''}" aria-pressed="${selected}" ${attrs}>${selected?icon('check'):''}${esc(label)}</button>`;
