const art=(k,cls='',extra='')=>`<div class="art ${cls}" ${extra}>${artSvg(k)}</div>`;
function row(a,{extra='',add=false}={}){const added=state.plan.includes(a.id);return `<${add?'div':'button'} class="artist-row" ${add?'':attr('artist',`data-artist="${a.id}"`)}>${art(a.art)}<div class="row-copy"><h3>${esc(a.name)}</h3><p>${esc(a.medium)} <span class="dot-separator">·</span> ${esc(a.region)}</p>${extra?`<span class="availability">${esc(extra)}</span>`:''}</div>${add?ib(added?'check':'plus',added?`${a.studio} added`:`Add ${a.studio}`,action('add-stop',`data-artist="${a.id}"`),added?'saved':'transparent'):icon('chevron-right','row-chevron')}</${add?'div':'button'}>`}
function nav(active){return `<nav class="bottom-nav" aria-label="App navigation">${[['explore','compass','Explore'],['map','map','Map'],['plan','route','Plan'],['settings','ellipsis','More']].map(([id,sym,label])=>`<button ${attr(id)} class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(sym)}<span>${label}</span></button>`).join('')}</nav>`}
const status=()=>`<div class="status-bar"><span>9:41</span><div class="island"></div><div class="status-icons">${icon('signal')}${icon('wifi')}${icon('battery-full')}</div></div>`;
